//! Generated Rust bindings for Homebound Labs shared protobuf contracts.
//!
//! Everything below `homebound::` is generated by `protoc-gen-prost` from
//! `proto/` and committed, in line with this repo's rule that generated code
//! is reviewable in PRs rather than produced at build time. **Do not edit the
//! generated files.** Change the `.proto` and re-run `./scripts/generate.sh`.
//!
//! This file is the one hand-written part of the crate.
//!
//! # no_std
//!
//! Default features pull in `std`. Device firmware
//! ([`homebound-labs/homebound-fw`](https://github.com/homebound-labs/homebound-fw))
//! runs `no_std`, so build with `default-features = false`:
//!
//! ```toml
//! homebound-protos = { git = "https://github.com/homebound-labs/protos", default-features = false }
//! ```
//!
//! prost still needs a heap in that configuration: generated messages use
//! `String` and `Vec` via `prost::alloc`, so a `no_std` consumer must
//! register a global allocator.

#![cfg_attr(not(feature = "std"), no_std)]
// Generated code sets its own conventions; linting it produces noise nobody
// can act on without changing the generator.
#![allow(clippy::all, clippy::pedantic)]
#![allow(rustdoc::bare_urls, rustdoc::broken_intra_doc_links, rustdoc::invalid_html_tags)]

include!("mod.rs");
